import{_ as r,c as t,o,ag as a}from"./chunks/framework.BtwP-r-R.js";const i="/14B-POO-A26/assets/recherche_dicho1.Brdh5MMH.png",c="/14B-POO-A26/assets/recherche_dicho2.BH1gUlse.png",n="/14B-POO-A26/assets/recherche_dicho3.CbIKb-yn.png",s="/14B-POO-A26/assets/recherche_dicho4.BjRS6cTU.png",f=JSON.parse('{"title":"La recherche dichotomique","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"recherche_dichotomique.md","filePath":"recherche_dichotomique.md"}'),u={name:"recherche_dichotomique.md"};function l(h,e,p,d,m,_){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="la-recherche-dichotomique" tabindex="-1">La recherche dichotomique <a class="header-anchor" href="#la-recherche-dichotomique" aria-label="Permalink to &quot;La recherche dichotomique&quot;">​</a></h1><p>La recherche dichotomique est une manière efficace et rapide de rechercher un élément dans une structure de données <strong>triée</strong> (pour nous, ce sera un vecteur trié).</p><p>En effet, jusqu&#39;à maintenant vous aviez peut-être l&#39;habitude de parcourir un tableau du début jusqu&#39;à ce que vous trouviez la valeur, et parfois jusqu&#39;à la dernière case du vecteur. Cette méthode est une recherche séquentielle, facile à écrire et à mettre en œuvre, mais est efficace en matière de temps d&#39;exécution que si le vecteur parcouru est très petit.</p><h2 id="fonctionnement" tabindex="-1">Fonctionnement <a class="header-anchor" href="#fonctionnement" aria-label="Permalink to &quot;Fonctionnement&quot;">​</a></h2><ul><li><p>On dispose d’un tableau trié de valeur, et nous cherchons à déterminer si la valeur est présente dans le vecteur.</p></li><li><p>Pour cela, nous procédons par dichotomie :</p><ul><li>Nous regardons l’élément qui se trouve au milieu du vecteur et nous le comparons avec la valeur recherchée. <ul><li>S’ils sont égaux alors nous avons trouvé la valeur.</li><li>Si la valeur est inférieure, alors nous poursuivons la recherche dans la première moitié du vecteur.</li><li>Si la valeur est supérieure, alors nous poursuivons la recherche dans la deuxième moitié du vecteur.</li></ul></li></ul></li><li><p>On exécute l’étape précédente tant que nous n’avons pas trouvé la valeur ou qu’il n’y a plus aucun élément dans le vecteur.</p></li></ul><p>Voici un exemple : <img src="'+i+'" alt="Valeur recherchée"></p><p><strong>Première recherche</strong><img src="'+c+'" alt="Comparaison milieu"></p><p><strong>Deuxième recherche</strong><img src="'+n+'" alt="Comparaison moitié de droite"></p><p><strong>Troisième recherche</strong><img src="'+s+'" alt="valeur trouvée"></p><h3 id="demonstration" tabindex="-1">Démonstration <a class="header-anchor" href="#demonstration" aria-label="Permalink to &quot;Démonstration&quot;">​</a></h3><p>Téléchargez la solution : <a href="https://gitlab.com/420-14b-fx/contenu/-/blob/main/bloc3/cours%2027/ExempleOptimisationRechDicho.zip?ref_type=heads" target="_blank" rel="noreferrer">S14C1-ExempleOptimisationRechDicho</a></p><p>:::</p>',12)])])}const q=r(u,[["render",l]]);export{f as __pageData,q as default};
